  "No mailing lists in the stored mail.": "\u0412 \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d\u043d\u043e\u0439 \u043f\u043e\u0447\u0442\u0435 \u043d\u0435\u0442 \u0440\u0430\u0441\u0441\u044b\u043b\u043e\u043a.",
  "Mailing lists": "\u0420\u0430\u0441\u0441\u044b\u043b\u043a\u0438",
  "Unsubscribe from {name}": "\u041e\u0442\u043f\u0438\u0441\u0430\u0442\u044c\u0441\u044f \u043e\u0442 \u00ab{name}\u00bb",
  "No way to unsubscribe that Mail can trust.": "\u041d\u0435\u0442 \u0441\u043f\u043e\u0441\u043e\u0431\u0430 \u043e\u0442\u043f\u0438\u0441\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u041f\u043e\u0447\u0442\u0430 \u043c\u043e\u0436\u0435\u0442 \u0434\u043e\u0432\u0435\u0440\u044f\u0442\u044c.",
  "Its unsubscribe address is not at the sender's domain: unsubscribe from a message of this list.": "\u0410\u0434\u0440\u0435\u0441 \u0434\u043b\u044f \u043e\u0442\u043f\u0438\u0441\u043a\u0438 \u043d\u0435 \u043d\u0430 \u0434\u043e\u043c\u0435\u043d\u0435 \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044f: \u043e\u0442\u043f\u0438\u0448\u0438\u0442\u0435\u0441\u044c \u0438\u0437 \u043f\u0438\u0441\u044c\u043c\u0430 \u044d\u0442\u043e\u0439 \u0440\u0430\u0441\u0441\u044b\u043b\u043a\u0438.",
  "{count} message": { one: "{count} \u043f\u0438\u0441\u044c\u043c\u043e", few: "{count} \u043f\u0438\u0441\u044c\u043c\u0430", many: "{count} \u043f\u0438\u0441\u0435\u043c", other: "{count} \u043f\u0438\u0441\u044c\u043c\u0430" },
  "{count} messages": { one: "{count} \u043f\u0438\u0441\u044c\u043c\u043e", few: "{count} \u043f\u0438\u0441\u044c\u043c\u0430", many: "{count} \u043f\u0438\u0441\u0435\u043c", other: "{count} \u043f\u0438\u0441\u044c\u043c\u0430" },
  "{count} unread": "\u043d\u0435\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u043d\u044b\u0445: {count}",
  "the list refused the request": "\u0440\u0430\u0441\u0441\u044b\u043b\u043a\u0430 \u043e\u0442\u043a\u043b\u043e\u043d\u0438\u043b\u0430 \u0437\u0430\u043f\u0440\u043e\u0441",
  "the list's server failed": "\u0441\u0435\u0440\u0432\u0435\u0440 \u0440\u0430\u0441\u0441\u044b\u043b\u043a\u0438 \u043e\u0442\u0432\u0435\u0442\u0438\u043b \u043e\u0448\u0438\u0431\u043a\u043e\u0439",
  "the list could not be reached": "\u0434\u043e \u0440\u0430\u0441\u0441\u044b\u043b\u043a\u0438 \u043d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0434\u043e\u0441\u0442\u0443\u0447\u0430\u0442\u044c\u0441\u044f",
  "the list's address is not allowed": "\u0430\u0434\u0440\u0435\u0441 \u0440\u0430\u0441\u0441\u044b\u043b\u043a\u0438 \u043d\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043d",
  "the list did not answer": "\u0440\u0430\u0441\u0441\u044b\u043b\u043a\u0430 \u043d\u0435 \u043e\u0442\u0432\u0435\u0442\u0438\u043b\u0430",
  "the request failed": "\u0437\u0430\u043f\u0440\u043e\u0441 \u043d\u0435 \u0443\u0434\u0430\u043b\u0441\u044f",
  "archive": "\u0432 \u0430\u0440\u0445\u0438\u0432",
  "move to Trash": "\u0432 \u041a\u043e\u0440\u0437\u0438\u043d\u0443",
