  "The username cannot be used.": "\u042d\u0442\u043e \u0438\u043c\u044f \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f.",
  "The SMTP server refused the login.": "\u0421\u0435\u0440\u0432\u0435\u0440 SMTP \u043e\u0442\u043a\u043b\u043e\u043d\u0438\u043b \u0432\u0445\u043e\u0434.",
  "SMTP works.": "SMTP \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442.",
  "SMTP for": "SMTP \u0434\u043b\u044f",
  "TLS (usually port 465)": "TLS (\u043e\u0431\u044b\u0447\u043d\u043e \u043f\u043e\u0440\u0442 465)",
  "STARTTLS (usually port 587)": "STARTTLS (\u043e\u0431\u044b\u0447\u043d\u043e \u043f\u043e\u0440\u0442 587)",
  "Username": "\u0418\u043c\u044f \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f",
  "Leave empty to use the IMAP username.": "\u041e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043f\u0443\u0441\u0442\u044b\u043c, \u0447\u0442\u043e\u0431\u044b \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u0438\u043c\u044f \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f IMAP.",
  "Account password": "\u041f\u0430\u0440\u043e\u043b\u044c \u0443\u0447\u0451\u0442\u043d\u043e\u0439 \u0437\u0430\u043f\u0438\u0441\u0438",
  "This server is outside": "\u042d\u0442\u043e\u0442 \u0441\u0435\u0440\u0432\u0435\u0440 \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0432\u043d\u0435",
  "Use an existing folder": "\u0418\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0443\u044e \u043f\u0430\u043f\u043a\u0443",
  "Snoozed mail waits there and comes back to the Inbox at the time you pick.": "\u041e\u0442\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0435 \u043f\u0438\u0441\u044c\u043c\u0430 \u0436\u0434\u0443\u0442 \u0442\u0430\u043c \u0438 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0442\u0441\u044f \u0432\u043e \u00ab\u0412\u0445\u043e\u0434\u044f\u0449\u0438\u0435\u00bb \u0432 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u0435 \u0432\u0440\u0435\u043c\u044f.",
  "There is no other folder that can hold snoozed mail.": "\u041d\u0435\u0442 \u0434\u0440\u0443\u0433\u043e\u0439 \u043f\u0430\u043f\u043a\u0438, \u0433\u0434\u0435 \u043c\u043e\u0433\u0443\u0442 \u043b\u0435\u0436\u0430\u0442\u044c \u043e\u0442\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0435 \u043f\u0438\u0441\u044c\u043c\u0430.",
  "Use an existing folder\u2026": "\u0418\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0443\u044e \u043f\u0430\u043f\u043a\u0443\u2026",
