  "It leaves the Inbox and comes back unread at that time, while BB runs.": "\u041f\u0438\u0441\u044c\u043c\u043e \u0443\u0439\u0434\u0451\u0442 \u0438\u0437 \u00ab\u0412\u0445\u043e\u0434\u044f\u0449\u0438\u0445\u00bb \u0438 \u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f \u043d\u0435\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u043d\u044b\u043c \u0432 \u044d\u0442\u043e \u0432\u0440\u0435\u043c\u044f, \u043f\u043e\u043a\u0430 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 BB.",
  "Snooze times": "\u0412\u0440\u0435\u043c\u044f \u043e\u0442\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u043d\u0438\u044f",
  "Pick a date and time": "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0430\u0442\u0443 \u0438 \u0432\u0440\u0435\u043c\u044f",
  "Snooze until": "\u041e\u0442\u043b\u043e\u0436\u0438\u0442\u044c \u0434\u043e",
