  "Summarize again": "\u0421\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0441\u0432\u043e\u0434\u043a\u0443 \u0437\u0430\u043d\u043e\u0432\u043e",
  "The summary was stopped.": "\u0421\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441\u0432\u043e\u0434\u043a\u0438 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e.",
  "The conversation has new messages since this summary.": "\u041f\u043e\u0441\u043b\u0435 \u044d\u0442\u043e\u0439 \u0441\u0432\u043e\u0434\u043a\u0438 \u0432 \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u043a\u0435 \u043f\u043e\u044f\u0432\u0438\u043b\u0438\u0441\u044c \u043d\u043e\u0432\u044b\u0435 \u043f\u0438\u0441\u044c\u043c\u0430.",
