  "Unsubscribe from this list?": "\u041e\u0442\u043f\u0438\u0441\u0430\u0442\u044c\u0441\u044f \u043e\u0442 \u044d\u0442\u043e\u0439 \u0440\u0430\u0441\u0441\u044b\u043b\u043a\u0438?",
  "One click to": "\u041e\u0434\u0438\u043d \u0449\u0435\u043b\u0447\u043e\u043a \u043f\u043e \u0430\u0434\u0440\u0435\u0441\u0443",
